import { View, Text, FlatList, RefreshControl, StyleSheet } from "react-native";
import { useState } from "react";
import { registerRootComponent } from "expo";

const BASE = [
  { id: "p1", name: "Утасгүй чихэвч", price: "159,000₮" },
  { id: "p2", name: "Гар цаг X100", price: "249,000₮" },
  { id: "p3", name: "Нарны шил", price: "89,000₮" },
];
const FRESH = { id: "p0", name: "Шинэ: Ухаалаг бугуйвч", price: "399,000₮" };

function App() {
  const [items, setItems] = useState(BASE);
  const [refreshing, setRefreshing] = useState(false);
  const onRefresh = () => {
    setItems([FRESH, ...BASE]);
  };
  // энд бичнэ үү: FlatList-д refreshControl={<RefreshControl .../>} нэм
  return (
    <FlatList
      style={styles.list}
      data={items}
      keyExtractor={(item) => item.id}
      renderItem={({ item }) => (
        <View testID="product" style={styles.row}>
          <Text style={styles.name}>{item.name}</Text>
          <Text style={styles.price}>{item.price}</Text>
        </View>
      )}
    />
  );
}

const styles = StyleSheet.create({
  list: { flex: 1, backgroundColor: "#f8fafc" },
  row: { flexDirection: "row", justifyContent: "space-between", padding: 16, backgroundColor: "#fff" },
  name: { fontSize: 16 },
  price: { fontSize: 16, fontWeight: "bold", color: "#2563eb" },
});

registerRootComponent(App);

import { View, Text, FlatList, RefreshControl, StyleSheet } from "react-native";
import { useState } from "react";
import { registerRootComponent } from "expo";

const BASE = [
  { id: "p1", name: "Утасгүй чихэвч", price: "159,000₮" },
  { id: "p2", name: "Гар цаг X100", price: "249,000₮" },
  { id: "p3", name: "Нарны шил", price: "89,000₮" },
];
const FRESH = { id: "p0", name: "Шинэ: Ухаалаг бугуйвч", price: "399,000₮" };

function App() {
  const [items, setItems] = useState(BASE);
  const [refreshing, setRefreshing] = useState(false);
  const onRefresh = () => {
    setItems([FRESH, ...BASE]);
  };
  return (
    <FlatList
      style={styles.list}
      data={items}
      keyExtractor={(item) => item.id}
      refreshControl={<RefreshControl refreshing={refreshing} onRefresh={onRefresh} />}
      renderItem={({ item }) => (
        <View testID="product" style={styles.row}>
          <Text style={styles.name}>{item.name}</Text>
          <Text style={styles.price}>{item.price}</Text>
        </View>
      )}
    />
  );
}

const styles = StyleSheet.create({
  list: { flex: 1, backgroundColor: "#f8fafc" },
  row: { flexDirection: "row", justifyContent: "space-between", padding: 16, backgroundColor: "#fff" },
  name: { fontSize: 16 },
  price: { fontSize: 16, fontWeight: "bold", color: "#2563eb" },
});

registerRootComponent(App);
